solutions.naive:
class Solution:
    def minStickers(self, stickers: list[str], target: str) -> int:
        counts = []
        for st in stickers:
            d = {}
            for ch in st:
                d[ch] = d.get(ch, 0) + 1
            counts.append(d)
        def apply(rem: str, d: dict) -> str:
            left = []
            used = d.copy()
            for ch in rem:
                if used.get(ch, 0):
                    used[ch] -= 1
                else:
                    left.append(ch)
            return ''.join(left)
        def dfs(rem: str) -> int:
            if not rem:
                return 0
            best = 10**9
            for d in counts:
                if rem[0] not in d:
                    continue
                nxt = apply(rem, d)
                if len(nxt) < len(rem):
                    sub = dfs(nxt)
                    if sub != -1:
                        best = min(best, 1 + sub)
            return -1 if best == 10**9 else best
        return dfs(''.join(sorted(target)))

