solutions.optimal:
class Solution:
    def minStickers(self, stickers: list[str], target: str) -> int:
        n = len(target)
        full = (1 << n) - 1
        dp = [10**9] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            if dp[mask] == 10**9:
                continue
            for st in stickers:
                nxt = mask
                for ch in st:
                    for i, need in enumerate(target):
                        if need == ch and not (nxt >> i) & 1:
                            nxt |= 1 << i
                            break
                if dp[mask] + 1 < dp[nxt]:
                    dp[nxt] = dp[mask] + 1
        return -1 if dp[full] == 10**9 else dp[full]

